"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["4194"],{9734(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>h,frontMatter:()=>s,contentTitle:()=>r,toc:()=>d,assets:()=>l});var i=JSON.parse('{"id":"how-to/hardware/samples/raspberry-hl-mqtt","title":"Getting started with HL module on RaspberryPI","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/hardware/samples/raspberry-hl-mqtt.md","sourceDirName":"how-to/hardware/samples","slug":"/how-to/hardware/samples/raspberry-hl-mqtt","permalink":"/personal-av-docs/docs/how-to/hardware/samples/raspberry-hl-mqtt","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/hardware/samples/raspberry-hl-mqtt.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Getting started with HL module on RaspberryPI","sidebar_label":"Getting started with HL module on Raspbe","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/howto/hardware/samples/raspberry-hl-mqtt","format":"md"}}'),o=t(4848),a=t(8453);let s={title:"Getting started with HL module on RaspberryPI",sidebar_label:"Getting started with HL module on Raspbe",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/howto/hardware/samples/raspberry-hl-mqtt",format:"md"},r,l={},d=[];function c(e){let n={a:"a",code:"code",em:"em",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(n.p,{children:[":::note Edition\n",(0,o.jsx)(n.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(n.a,{href:"https://doc.airvantage.net/av/howto/hardware/samples/raspberry-hl-mqtt",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(n.p,{children:"Getting started with HL module on RaspberryPI\nThis tutorial describes how to create a communication with AirVantage Cloud from a\nRaspberryPI\nequiped with a\nHL wireless module\n.\nThe following use cases are covered:\nSending some custom data such as sensor value or application data from RaspberryPI to  AirVantage Cloud\nSending some commands or configuration from AirVantage Cloud to RaspberryPI\nTo implement this solution, MQTT protocol will be used\nTo achieve the above objective, following main steps are covered:\nHow to setup your device: Hardware connection, AT command interface and IP connectivity\nHow to register your device on AirVantage\nHow to communicate with AirVantage using MQTT\nPrerequisite\nLinkwave\u2019s PiloT HL Shield for RaspberryPI + AirPrime HL module + Antenna\nRaspberryPI + SD Card with Raspian loaded + Power adaptor + keyboard + HDMI cable\nSIM card (Micro SIM format FF3) with data call plan\nHave an account on AirVantage server:\neu.airvantage.net\nPart references used in this tutorial\nHL Shield - The PiloT\nRaspberryPI B+\nAntenna\n1 /\nHardware setup\n2 /\nSetting up the connectivity\n3 /\nMQTT data exchange\nAny issues ?\nIf you encounter any issue to set up your device, don\u2019t hesitate to use the\ndeveloper forum\nto benefit from the developer community experience.\nStep 1: Hardware setup\nThis step starts with interfacing the HL module with your Raspberry.\nAT Command\ninterface should then be in place to enable the host application to control the HL Module.\nFinally,\nIP Connectivity\nis created using PPP dial-up to enable host applications to communicate with remote servers.\nConnect Hardware\nThe HL Module should be in the PiloT\u2019s module socket.\nConnect the antenna to the PiloT shield\nThe SD card with Raspbian shall be inserted into the RaspberryPI\nStack the PiloT Shield over the RaspberryPI\nInsert SIM card\nSelect one of the following mean to access the Raspian console:\nUse USB Keyboard and HDMI cable for direct access to console\nUse Ethernet or WiFi for remote access to console with SSH\nSwitch on the RaspberryPI\nInterface with HL Module\nThe PiloT HL shield offers 2 hardware interfaces (USB or UART) for your RaspberryPI to control the HL module.\nSelect the hardware interface you\u2019d like to use in this tutorial:\nUART Interface\nThe Raspberry PI serial port (UART) is /dev/ttyAMA0\nBy default the Raspberry Pi\u2019s serial port is configured to be used for console input/output. To be able to use the serial port to connect and talk to the HL module, the serial port console login needs to be disabled, as follow:\nComment out the following line in /etc/inittab file:\n#T0:23:respawn:/sbin/getty -L ttyAMA0 115200 vt100\nAfter rebooting your RaspberryPI, AT commands can be issued over /dev/ttyAMAO\nIf you are using\nHL65xx\nmodule, module, GPIO6 and GPIO21 has to be configured as OUTPUT in order to enable Power supply and to turn on the module\nYou can use different library/tool to setup these 2 GPIO, for instance:\nbw_rpi_tools\nor\nwiringPI\n.\nConfigure the following at every system reboot:\nEnable Power supply on the module : define GPIO6 as OUTPUT and set it to Logic 1 (HIGH)\nTurn On the module : define GPIO21 as OUTPUT, set it to Logic 1 (HIGH) for at least 2 seconds, then set it to Logic 0 (LOW)\nBelow is an example to turn on the HL65xx module using wiringPI library. Makefile and turnOnHL6.c\nDEBUG   = -O3\nCC      = gcc\nINCLUDE = -I/usr/local/include\nCFLAGS  = $(DEBUG) -c -Wall $(INCLUDE) -Winline -pipe\nLDFLAGS = -L/usr/local/lib\nLDLIBS  = -lwiringPi -lwiringPiDev -lpthread -lm\nSOURCES = turnOnHL6.c\nOBJECTS = $(SOURCES:.c=.o)\nEXECUTABLE = turnOnHL6\nall: $(SOURCES) $(EXECUTABLE)\n$(EXECUTABLE): $(OBJECTS)\n$(CC) -o $@ $(OBJECTS) $(LDFLAGS) $(LDLIBS)\n.c.o:\n$(CC) $(CFLAGS) $< -o $@\n#include <stdio.h>\n#include <unistd.h>\n#include <wiringPi.h>\n#define GPIO_MODULE_ON        29    //this is BCM GPIO_21\n#define GPIO_MODULE_POWER_ON  22    //this is BCM GPIO_06\nint main()\n{\n//wiringPi lib setup\nwiringPiSetup();"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:"//configure GPIO_21 & GPIO_06 as OUTPUT\npinMode(GPIO_MODULE_ON, OUTPUT);\npinMode(GPIO_MODULE_POWER_ON, OUTPUT);\n\n//set GPIO_21 and GPIO_06 to Logic 1\ndigitalWrite(GPIO_MODULE_POWER_ON, HIGH);\ndigitalWrite(GPIO_MODULE_ON, HIGH);\n\n//wait for 5 seconds\nsleep(5);\n\n//set GPIO06 to Logic 0\ndigitalWrite(GPIO_MODULE_ON, LOW);\n\nreturn 0;\n"})}),"\n",(0,o.jsx)(n.p,{children:"}\nUSB Interface (Not Available with HL65xx Modules)\nPlease note that USB interface is not available if HL65xx module is snapped in the PiloT shield\nConnect the PiloT shield\u2019s micro USB port to RaspberryPI USB port, as shown in the picture\nDevice ports ttyACM0 through ttyACM4 shall be available: /dev/ttyACM0 through /dev/ttyACM4\nAT commands can be issued over the following ports: ttyACM0, ttyACM3 and ttyACM4\nCheck AT-Command Interface\nUse a serial terminal (e.g. minicom) to make sure that the AT interface can be established. To install minicom proceed as follow (internet access required):\nsudo apt-get install minicom\nInitialize the serial terminal to open the device port (e.g. /dev/ttyACM0 or /dev/ttyAMA0, depending of the hardware interface you\u2019ve selected in the previous section) on which the HL module is attached to, for instance:\nsudo minicom -D\n/dev/ttyAMA0\nThe following AT commands shall be entered within minicom to perform some sanity checking:\nAT\n: expected response\nOK\n. If not, make sure the board is powered on (the\nVBAT\nled should be on) and check minicom baudrate setting (default HL baudrate should be 115200), using\nminicom -s\nAT+CPIN?\n: expected response\nREADY\nif not, SIM PIN may be entered using the\nAT+CPIN\ncommand. e.g.\nAT+CPIN=\u201C1234\u201D\nAT+IPR?\n: the operating baudrate should be returned, please use this baudrate in the remaining tutorial\nAT+CREG?\n: to check the network registration status, expected response +CREG:x,1 (registered, home network) or +CREG:x,5 (roaming)\nAT+CGREG?\n: to check the GPRS registration status, expected response +CGREG:x,1 (registered, home network) or +CGREG:x,5 (roaming)\nAT+CSQ\n: returns \u201CRSSI\u201D,\u201CBER\u201D. RSSI indicates the signal strength in dBm, a value of 99 reflects no signal detected or not known\nIssue\nAT+CGSN\ncommand to retrieve module\u2019s IMEI, please note the IMEI, it will be used in upcoming tutorial steps\nIssue\nAT+KGSN=3\ncommand to retrieve module\u2019s Serial Number, please note the S/N for future use\nAT Commands Integration in the Device\nIn the above hands-on sections, we were able to manually send AT-Commands, using minicom. This sub-section aims to facilitate the AT-Command support within your device application.\nIntegration Helper\nThe aforementioned AT commands must be issued programmatically within your device application. And the response must be filtered and analyzed by the device application. For instance, the returned IMEI should be extracted from\nAT+CGSN\nresponse, IMEI is required to register the HL module on AirVantage platform.\nFor your convenience, a\nsample AT command line tool\ncan be adapted and integrated into your device application to rapidly gain AT-Command capabilities and to control the HL module.\nThe provided sample AT command can also be used as is, as follow:\n./hl-atcmd   -d devicePort   -b baudrate   -f atcmd-filter   at-cmd\nFor instance:\n*\n./hl-atcmd   -d /dev/ttyAMA0   -b 115200    -f AT+CGSN    AT+CGSN\nwill return the filtered response which is the IMEI. Full response will be returned if no filter is specified.\n*\n./hl-atcmd   -d /dev/ttyAMA0   -b 115200    -f +KGSN:    \u2018AT+KGSN=\u201C3\u201D\u2019\nwill return the filtered response which is the Serial Number. Full response will be returned if no filter is specified.\n* SIM PIN may be entered as follow:\n./hl-atcmd   -d /dev/ttyAMA0   -b 115200    \u2018AT+CPIN=\u201C1234\u201D\u2019"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:["Any AT-commands as documented in the AT-command specification can be executed using this command line (shell scriptable)\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:["If the AT command is not responding, make sure that device port and the baudrate (\nAT+IPR?\n) are both correct.\nIn Step 1, we\u2019ve covered how to:\nConnect HL Module to RaspberryPI\nSend AT Commands to HL Module\nRetrieve HL Modules\u2019s IMEI & Serial Number using AT+CGSN & AT+KGSN=3 commands\nStep 2: Setting up the connectivity\nSetup PPP\nPPP daemon (pppd) is available on Linux-based system. It can be installed on RaspberryPI as follow (internet access required):\nsudo apt-get install\nppp\nPPP dial-up configuration is defined by a pppOptionFile, located in the /etc/ppp/peers directory. It is depending on a chatscript file (in /etc/chatscripts directory).\nThe content of pppOptionFile is carrier specific and can be generated with pppconfig utility, refer to \u201Cman pppconfig\u201D pages.\nOrange-France specific pppOptionFile and chatscript are provided\nhere\nas example.\nNote that the device port and the baud rate are stated in the option file\nLaunch PPP\nQuit minicom before launching PPP\nStart PPP daemon by specifying the filename of the pppOptionFile (located in\n/etc/ppp/peers\ndirectory) as follow\nsudo\npppd\ncall\npppOptionFile\n&\nThe following statements in the log indicate a successful outcome of the PPP daemon:\n\u201Clocal IP address\u2026\u201D, \u201Cremote IP address\u2026\u201D, \u201Cip-up finished\u201D\nPPP interface (e.g. ppp0) should be listed with associated IP address upon ifconfig commmand\nIP connectivity can be assessed with a ping command (e.g. ping ",(0,o.jsx)(n.a,{href:"http://www.google.com",children:"www.google.com"}),')\nWhen you will need to close the IP connectivity later, it is highly recommended not to stop the PPP daemon with\nCTRL-C\n. Proceed as following to properly terminate the PPP session:\nIssue\nps -ef | grep pppd\nin the console\nIdentify the\npid\nassociated to the running\npppd\nprocess\nIssue\nsudo kill -s SIGHUP pid\nso the pppd will have the modem to hangup properly the data call.\nIn Step 2, we\u2019ve covered how to:\nUse PPP dial-up to obtain IP Connectivity\nStep 3: MQTT data exchange with AirVantage\nMQTT\nis a lightweight publish/subscribe messaging protocol. A Device/Client application can\npublish\na message to MQTT broker under a uniquely named\ntopic\n. The server then instantly relays this message to other connected Device/Client applications having subscribed to the same named\ntopic\n.\nOne-to-one and one-to-many IoT messaging approaches mechanism can thus come to life.\nAirVantage server implements MQTT Broker functionalities. It has the ability to receive, to retain then to relay MQTT messages. AirVantage supports MQTT QoS Level 1 (messages delivered at least once with confirmation required).\nThis section starts with hands-on steps showing you how to publish messages to and receive data from AirVantage, using Mosquitto command line tools. Key integration aspects of MQTT client into your device application is then highlighted.\nAny client implementing MQTT can be used to exchange data with AirVantage. In this tutorial, we will use\nMosquitto\n, an open source solution implementing MQTT which can be installed on the host (e.g. run the following command for RaspberryPI or PC running Ubuntu) as follow (internet access required):\nsudo apt-get install mosquitto-clients\nPublish MQTT Messages\nMQTT messaging content exchanged between the Device and AirVantage Server is defined by Application Model and the payload should be JSON encoded:\nEach sample of a\nvariable\nhas a timestamp (elapsed ms since Jan-1970) and a value. It is possible to send a collection (or array) of sample at once.\nThe variable is identified by it\u2019s asset id and the path\nFor instance, the following MQTT message to be published contains 2 samples of\nTemperature\nand\nHumidity\nvariable\nas defined in\nStep 2-\u201CDefine Data Model\u201D\n:\n[\n{ "machine.temperature": [\n{"timestamp": 1425937636000, "value":"21"},\n{"timestamp": 1425939843000, "value":"20.9"} ]\n},\n{ "machine.humidity": [\n{"timestamp": 1425937636000, "value":"37"},\n{"timestamp": 1425939843000, "value":"38"} ]\n}\n]\nBelow is another message example publishing temperature and humidity sample without specifying the timestamp. AirVantage will assign the current timestamp to samples.\n{\n{"machine.temperature" : "20.9"},\n{"machine.humidity" : 38}\n}\nAbove message(s) shall be published to topic: \u201C%SERIAL/messages/json\u201D, where %SERIAL is the Serial Nuber of the module as retrieved in Step 1\nPublish message to AirVantage, using Mosquitto command line:\nSave the above sample JSON message into a file (e.g. pub-msg.txt)\nPublish the file\u2019s content to AirVantage, as follow\n',(0,o.jsx)(n.em,{children:"mosquitto_pub -h eu.airvantage.net -t %SERIAL/messages/json -f pub-msg.txt -u %SERIAL -P %password"}),'<br>\n(where %SERIAL is the Serial Number of the module as retrieved in Step 1, %password is the password defined in Step 2)\nView Pusblished data on Web portal\nLog into\nAirVantage Web portal\nGo to Monitor > Systems\nSearch for your Systems/Device using filters (e.g. Label, Serial Number)\nClick on your System/Device to view monitoring page\nScroll down to \u201CLast Communication\u201D panel to view data published by the Device\n\u201CTimeline\u201D option can be used to view history events related to Device communication with AirVantage server\nSubscribing to MQTT topic\nIn order to receive data from AirVantage, the device application must subscribe to the topic: \u201C%SERIAL/tasks/json\u201D.\nLet\u2019s do this using Mosquitto command line as follow:\nmosquitto_sub -h eu.airvantage.net -t %SERIAL/tasks/json -u %SERIAL -P %password\n(where %SERIAL is the SERIAL NUMBER of the module as retrieved in Step 1, %password is the password defined in your system)\nIncoming data will be displayed as they arrive\u2026 now let\u2019s send some data\u2026\nSending MQTT data to Device from Web portal\nGo to Monitor > Systems\nSearch for your Device using filters (e.g. Label, IMEI)\nClick on your Device to view monitoring page\nClick on the \u201CMore\u201D button\n(located on top right), then select \u201CCustom Command\u201D\nBase on the Greenhouse Application Model (excerpt below), the \u201CTurn On\u201D command can be sent to the Device from AirVantage Web portal:\n<command path="TurnOn" default-label="Turn on">\n<parameter id="Light" default-label="Light" type="boolean" />\nSelect the action in the Command listbox and specify the corresponding parameters (e.g. Turn on Light)\nClick \u201CSend Command\u201D to fire the MQTT message to your Device\nReceiving MQTT Messages\nThe incoming MQTT message should be displayed by the previous\nmosquitto_sub\ncommand as follow:\n[{\n"uid":"9142df4c0b884683993521a3d5cf97f1",\n"timestamp":1426022121930,\n"command":{"id":"machine.TurnOn","params":{"Light":true}}\n}]\nThis message is JSON encoded and must be decoded by the Device (handled by the callback function) as follow:\nuid\nis the unique id of this MQTT message. This uid must be used to acknowledge the command.\ntimestamp is the jan-1970 elapsed timestamp of this message (in ms)\ncommand\nobject is composed of :\nid:\nasset id\n(machine) and the\ncommand path\n(TurnOn)\nparameter id (Light) set to\ntrue\nMQTT Client Integration in the Device\nIn the above hands-on steps, we were able to manually send messages to and receive data from AirVantage, using Mosquitto command line tools. This sub-section provides additional highlights on the integration of MQTT client into your device application. Addressing RaspberryPI\u2019s GPIO is also briefly described.\nMQTT Client Integration in the Device\nThe device application must implement MQTT Client functionalities in order to programmatically publish messages and to receive messages pertaining to subscribed topics. The specification can be found on\n',(0,o.jsx)(n.a,{href:"http://mqtt.org",children:"http://mqtt.org"}),"\n.\nThere are various MQTT libraries available on the web that can be leveraged to easily gain MQTT support in the device application.\nMost MQTT Client libraries expose 4 main functions:"]}),"\n"]}),"\n",(0,o.jsxs)(n.ol,{children:["\n",(0,o.jsxs)(n.li,{children:["Open Connection\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsx)(n.li,{children:"The device application should call this function first with the following parameters:"}),"\n",(0,o.jsx)(n.li,{children:"AirVantage MQTT server URL and port number: (eu.airvantage.net:1883)"}),"\n",(0,o.jsx)(n.li,{children:"Device Serial Number (retrieved in step 1,\n\u201CSend AT commands\u201D\n), for authentication purposes"}),"\n",(0,o.jsx)(n.li,{children:"Password (as defined in AirVantage)"}),"\n"]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["Message Publishing\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsx)(n.li,{children:"The device application calls this function to\npublish\nthe provided MQTT message (to be formatted as shown in step 3.2) to the specified\nTopic\n(URI style)"}),"\n",(0,o.jsx)(n.li,{children:"The publishing\ntopic\nshall be \u201C%SERIAL/messages/json\u201D, where %SERIAL is the Serial Number of the module as retrieved in Step 1"}),"\n"]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["Topic Subscription\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsx)(n.li,{children:"The device app calls this function along with a\nTopic\nto\nsubscribe\nto and a callback function to decode and parse the incoming MQTT message pertaining to the\ntopic"}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,o.jsx)(n.li,{children:"The subscription\ntopic\nshall be \u201C%SERIAL/tasks/json\u201D, where %SERIAL is the Serial Number of the module as retrieved in Step 1\n4. Close Connection\nNote that, in the previous hands-on section, the publishing command (mosquitto_pub) and subscription command (mosquitto_sub), are both encapsulated by Open connection and Close connection operations\nControlling RaspberryPI's GPIO\nControlling RaspberryPI\u2019s GPIO\nThe\nwiringPI\nlibrary can be easily integrated into the RaspberryPI in order to control GPIO.\nFor instance, to turn on a LED wired to the GPIO-0 of the RaspberryPI when the device receives the above\nTurnOn Light\ncommand\nBelow is the sample code:\n#include <wiringPi.h>\n...\nwiringPiSetup();\npinMode(0, OUTPUT);\n...\nif (turnOnLight)\n{\ndigitalWrite(0, HIGH);\n}\nelse\n{\ndigitalWrite(0, LOW);\n}\nTroubleshooting & Testing\nRefer to this\ntutorial\nfor further information on how to troubleshoot the connection and to interact with system/device\nIn Step 3, we\u2019ve covered how to:\nMQTT Client integration into device and connection with AirVantage\nFormatting, encoding and Publishing MQTT message\nViewing and collecting posted data on AirVantage\nSending MQTT data to Device from AirVantage\nSubscribing, receiving, decoding incoming MQTT messages\nSending command to RaspberryPI\u2019s GPIO port\nMQTT Sample Code\nAs described in the previous steps, enabling MQTT support in the device application requires the integration of MQTT protocol (may leveraging existing libraries). It also requires the implementation of JSON payload encoding/decoding and parsing/mapping of sensor/actuator/application data to the data model as defined in the application model.\nRefer to sample applications below (C code) for integration reference.\nGreenhouse\nThis sample (used in the above steps) publishes emulated Temperature and Humidity to AirVantage, and receives \u201CTurnOn\u201D command from AirVantage.\nYou may adapt this code to fit your needs.\nMQTT Spooler\nThis application automatically converts CVS data to MQTT messages prior publishing to server. It also automatically converts incoming MQTT messages (pertaining to a subscribed Topic) to CSV data. This app could be reused as a quick integration option (no need to deal with MQTT code) with your existing sensor/actuator based application."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},8453(e,n,t){t.d(n,{R:()=>s,x:()=>r});var i=t(6540);let o={},a=i.createContext(o);function s(e){let n=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),i.createElement(a.Provider,{value:n},e.children)}}}]);